var calculate = function(s) {
    let result = 0;
    let number = 0;
    let sign = 1;
    const stack = [];

    for (const ch of s) {
        if (ch >= '0' && ch <= '9') {
            number = number * 10 + (ch.charCodeAt(0) - 48);
        } else if (ch === '+' || ch === '-') {
            result += sign * number;
            number = 0;
            sign = ch === '+' ? 1 : -1;
        } else if (ch === '(') {
            stack.push(result);
            stack.push(sign);
            result = 0;
            sign = 1;
        } else if (ch === ')') {
            result += sign * number;
            number = 0;
            const outerSign = stack.pop();
            const outerResult = stack.pop();
            result = outerResult + outerSign * result;
        }
    }

    return result + sign * number;
};
